// 简化参数读取
template &lt;typename NodeT, typename ValueT&gt;
inline ValueT GetOrDeclare(NodeT&amp; node, const std::string&amp; name, const ValueT&amp; default_value) {
	if (!node.has_parameter(name)) {
		node.declare_parameter(name, rclcpp::ParameterValue(default_value));
	}

	const auto parameter = node.get_parameter(name);

	if constexpr (std::is_same_v&lt;ValueT, bool&gt;) {
		return parameter.as_bool();
	} else if constexpr (std::is_same_v&lt;ValueT, double&gt;) {
		return parameter.as_double();
	} else if constexpr (std::is_same_v&lt;ValueT, int&gt;) {
		return static_cast&lt;int&gt;(parameter.as_int());
	} else if constexpr (std::is_same_v&lt;ValueT, std::string&gt;) {
		return parameter.as_string();
	}
}
