	request-&gt;data = enable;

	auto future = enable_client_-&gt;async_send_request(request);
	if (future.wait_for(kResponseTimeout) != std::future_status::ready) {
		LOG(WARNING) &lt;&lt; &quot;[charge] AutoDocking service timeout: &quot; &lt;&lt; enable_service_name_;
		return false;
	}

	const auto response = future.get();
	if (!response || !response-&gt;success) {
		LOG(WARNING) &lt;&lt; &quot;[charge] AutoDocking service failed: &quot; &lt;&lt; enable_service_name_
					 &lt;&lt; &quot; msg=&quot; &lt;&lt; (response ? response-&gt;message : &quot;&lt;null&gt;&quot;);

	return false;
}
